services:
  configurator:
    image: localhost:5000/frappe/erpnext:${ERPNEXT_VERSION}

  backend:
    image: localhost:5000/frappe/erpnext:${ERPNEXT_VERSION}

  frontend:
    image: localhost:5000/frappe/erpnext:${ERPNEXT_VERSION}

  websocket:
    image: localhost:5000/frappe/erpnext:${ERPNEXT_VERSION}

  queue-short:
    image: localhost:5000/frappe/erpnext:${ERPNEXT_VERSION}

  queue-long:
    image: localhost:5000/frappe/erpnext:${ERPNEXT_VERSION}

  scheduler:
    image: localhost:5000/frappe/erpnext:${ERPNEXT_VERSION}

{
  "devDependencies": {
    "mermaid": "12.2.0",
    "vitepress": "2.0.0-alpha.20",
    "vitepress-mermaid-viewer": "0.5.1",
    "vitepress-sidebar": "1.40.0"
  },
  "scripts": {
    "docs:dev": "vitepress dev",
    "docs:build": "vitepress build",
    "docs:preview": "vitepress preview"
  },
  "pnpm": {
    "overrides": {
      "minimatch": "10.2.5",
      "picomatch": "4.0.4"
    }
  },
  "packageManager": "pnpm@10.28.2+sha512.41872f037ad22f7348e3b1debbaf7e867cfd448f2726d9cf74c08f19507c31d2c8e7a11525b983febc2df640b5438dee6023ebb1f84ed43cc2d654d2bc326264"
}

{
  "environment": {
    "BASE_SITE": "site-one.localhost",
    "BENCH_NETWORK": "bench-network",
    "DB_DATA_LOCATION": "/srv/frappe-bind-mounts/db-data",
    "DB_PASSWORD_SECRETS_FILE": "./test-db-password.txt",
    "EMAIL": "admin@example.com",
    "HASHED_PASSWORD": "[REDACTED]",
    "REDIS_QUEUE_DATA_LOCATION": "/srv/frappe-bind-mounts/redis-queue-data",
    "ROUTER": "site-one",
    "SITES_DATA_LOCATION": "/srv/frappe-bind-mounts/sites",
    "TRAEFIK_DOMAIN": "traefik.example.com"
  },
  "configurations": [
